export const AREAS=['Governance & GRC','Risk management','Security controls','Privacy & identity','Cloud security','AI security & governance','Application security','Supply-chain security','Threat intelligence','Incident response','Resilience & continuity','OT & industrial security','Data centers & facilities','Workforce & service management','Government & regional','Payment & sector assurance'];
export const TYPES=['Framework','Standard','Control catalog','Guidance','Maturity model','Assurance program','Knowledge base','Risk model'];
export const ACCESS=['Free resource','Free overview; paid material','Free overview; paid assessment'];
const HOSTS=['nist.gov','iso.org','cisecurity.org','owasp.org','owaspsamm.org','owaspai.org','opencre.org','mitre.org','cisa.gov','cloudsecurityalliance.org','isaca.org','aicpa-cima.com','opengroup.org','securecontrolsframework.com','hitrustalliance.net','securityforum.org','peoplecert.org','sfia-online.org','cyberriskinstitute.org','swift.com','pcisecuritystandards.org','ncsc.gov.uk','iasme.co.uk','cyber.gov.au','nzism.gcsb.govt.nz','csa.gov.sg','nca.gov.sa','enisa.europa.eu','fedramp.gov','defense.gov','ffiec.gov','energy.gov','nerc.com','isa.org','iec.ch','tiaonline.org','uptimeinstitute.com','ashrae.org','bicsi.org','nfpa.org','first.org','slsa.dev','scorecard.dev','cncf.io','oasis-open.github.io','rfc-editor.org','w3.org'];
export function safeSource(value){try{const u=new URL(value);return u.protocol==='https:'&&!u.username&&!u.password&&!u.port&&HOSTS.some(h=>u.hostname===h||u.hostname.endsWith('.'+h))?u.href:null;}catch{return null;}}
export function validateCatalog(catalog){
  if(catalog?.meta?.schema!==1||!Array.isArray(catalog.records)||!catalog.records.length||catalog.records.length>5000||catalog.meta.count!==catalog.records.length||!Number.isFinite(Date.parse(catalog.meta.assembledAt)))throw new Error('Invalid catalog structure');
  const ids=new Set();for(const r of catalog.records){
    for(const key of ['id','title','publisher','type','access','url','summary','edition'])if(typeof r[key]!=='string'||!r[key].trim()||r[key].length>2000)throw new Error('Invalid catalog field');
    if(!/^[a-z0-9-]{1,80}$/.test(r.id)||ids.has(r.id)||!TYPES.includes(r.type)||!ACCESS.includes(r.access)||!safeSource(r.url)||!Array.isArray(r.areas)||!r.areas.length||r.areas.length>8||r.areas.some(a=>!AREAS.includes(a))||!Array.isArray(r.regions)||!r.regions.length||r.regions.length>10||r.regions.some(a=>typeof a!=='string'||a.length>80))throw new Error('Invalid catalog record');ids.add(r.id);
  }return catalog;
}
export function normalize(text){return String(text??'').slice(0,8000).normalize('NFKD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/([a-z])([0-9])/g,'$1 $2').replace(/[^a-z0-9]+/g,' ').trim();}
export function distance(a,b,max=2){if(a===b)return 0;if(Math.abs(a.length-b.length)>max)return max+1;let older=null,prior=Array.from({length:b.length+1},(_,i)=>i);for(let i=1;i<=a.length;i++){const row=[i];let minimum=i;for(let j=1;j<=b.length;j++){let v=Math.min(row[j-1]+1,prior[j]+1,prior[j-1]+(a[i-1]===b[j-1]?0:1));if(older&&i>1&&j>1&&a[i-1]===b[j-2]&&a[i-2]===b[j-1])v=Math.min(v,older[j-2]+1);row[j]=v;minimum=Math.min(minimum,v);}if(minimum>max)return max+1;older=prior;prior=row;}return prior[b.length];}
const STOP=new Set('a an the to and for of in on i me my how do does can please find show need with framework frameworks'.split(' '));
const SYNONYMS={grc:['governance','risk','compliance'],infosec:['information','security'],ai:['ai','artificial','intelligence'],privacy:['privacy','pii'],cloud:['cloud'],cards:['card','payment','pci'],credit:['card','payment'],backup:['continuity','recovery'],backups:['continuity','recovery'],hacking:['adversary','threat','attack'],hackers:['adversary','threat','attack'],iam:['identity','authentication'],devsecops:['software','development','supply'],datacenter:['center','centre','facility'],datacentre:['center','centre','facility'],isms:['information','security','27001']};
export function createSearch(records){
  const entries=records.map(r=>({r,text:normalize([r.title,r.id,r.publisher,r.type,r.summary,r.edition,...r.areas,...r.regions].join(' ')),name:normalize(r.title+' '+r.id)}));for(const e of entries)e.words=[...new Set(e.text.split(' '))];
  const counts=key=>{const result=new Map();for(const r of records)for(const v of Array.isArray(r[key])?r[key]:[r[key]])result.set(v,(result.get(v)||0)+1);return [...result].sort((a,b)=>a[0].localeCompare(b[0]));};
  const facets={areas:AREAS.map(a=>[a,records.filter(r=>r.areas.includes(a)).length]),publishers:counts('publisher'),types:counts('type'),access:counts('access'),regions:counts('regions')};
  function search({query='',area='',publisher='',type='',access='',region='',sort='relevance',page=0,pageSize=20}={}){
    const q=normalize(String(query).slice(0,200)),terms=[...new Set(q.split(' ').filter(x=>x&&!STOP.has(x)))].slice(0,12);const matches=[];
    for(const e of entries){const r=e.r;if(area&&!r.areas.includes(area)||publisher&&r.publisher!==publisher||type&&r.type!==type||access&&r.access!==access||region&&!r.regions.includes(region))continue;let coverage=0,score=0;
      for(const term of terms){let best=0;for(const word of [term,...SYNONYMS[term]||[]]){if(e.words.includes(word))best=Math.max(best,3);else if(word.length>=2&&e.words.some(w=>w.startsWith(word)))best=Math.max(best,2);else if(word.length>=4&&!/^\d+$/.test(word)&&e.words.some(w=>w.length>=4&&distance(word,w,word.length>=8?2:1)<=(word.length>=8?2:1)))best=Math.max(best,1);}if(best){coverage++;score+=best;}}
      if(!terms.length||coverage)matches.push({r,coverage,score:score+(q&&e.name.includes(q)?20:0)+(q===normalize(r.id)?100:0)});
    }
    const strong=matches.filter(x=>x.coverage===terms.length),related=!!terms.length&&!strong.length,result=related?matches:strong;
    result.sort((a,b)=>sort==='publisher'?a.r.publisher.localeCompare(b.r.publisher)||a.r.title.localeCompare(b.r.title):sort==='title'?a.r.title.localeCompare(b.r.title):b.coverage-a.coverage||b.score-a.score||a.r.title.localeCompare(b.r.title));
    const size=Math.min(50,Math.max(1,Math.floor(Number(pageSize)||20))),p=Math.min(Math.max(0,Math.floor(Number(page)||0)),Math.max(0,Math.ceil(result.length/size)-1));return {total:result.length,related,page:p,pageSize:size,items:result.slice(p*size,(p+1)*size).map(x=>x.r)};
  }
  function suggest(query,filters={}){const q=normalize(query);if(q.length<2)return [];return [...AREAS.filter(a=>normalize(a).includes(q)).slice(0,3).map(a=>({type:'area',label:a,value:a,detail:'Subject area'})),...search({...filters,query,page:0,pageSize:5}).items.map(r=>({type:'record',label:r.title,value:r.id,detail:r.publisher+' · '+r.type}))].slice(0,8);}
  return {search,suggest,facets};
}
